def has_close_elements(numbers: list[float], threshold: float) -> bool:
    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    current_group = ""
    groups = []

    for char in paren_string:
        if char == '(':
            stack.append(char)
            current_group += char
        elif char == ')':
            stack.pop()
            current_group += char
            if not stack:
                groups.append(current_group)
                current_group = ""

    if current_group:
        groups.append(current_group)

    return groups

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        raise ValueError("Input list cannot be empty")

    mean = sum(numbers) / len(numbers)
    abs_deviations = [abs(x - mean) for x in numbers]
    return sum(abs_deviations) / len(numbers)

def find_topmost_carpet(n, carpets, point):
    # Check if the point is inside any of the carpets
    for i in range(n):
        if carpets[i][0] <= point[0] < carpets[i][0] + carpets[i][2] and carpets[i][1] <= point[1] < carpets[i][1] + carpets[i][3]:
            return i
    return -1

def max_value_on_paths(N, grid_values):
    # Initialize the dp table with the values from the grid
    dp = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            x, y, val = grid_values[i * N + j]
            dp[i][j] = val

    # Loop through the grid, computing the maximum sum of values between the current position and the boundary
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            elif i == 0:
                dp[i][j] = max(dp[i][j-1], dp[i][j])
            elif j == 0:
                dp[i][j] = max(dp[i-1][j], dp[i][j])
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1], dp[i][j])

    # Return the maximum sum of values on the two paths
    return max(dp[N-1][N-1], dp[0][N-1], dp[N-1][0], dp[0][0])

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    combinations = []
    for i in range(1, 10):
        for j in range(2*i, 10):
            for k in range(3*i, 10):
                if j == 2*i and k == 3*i:
                    combinations.append((i, j, k))
    return sorted(combinations)

