def max_energy(beads):
    # Dynamic programming approach
    n = len(beads)
    dp = [[0] * (n+1) for _ in range(n+1)]

    # Initialize the first row and column with the head values
    for i in range(1, n+1):
        dp[i][0] = beads[i-1]

    # Initialize the first column with the tail values
    for i in range(1, n+1):
        dp[0][i] = beads[i-1]

    # Fill in the table
    for i in range(1, n+1):
        for j in range(1, n+1):
            # Merge the two adjacent beads
            dp[i][j] = max(dp[i-1][j-1] * beads[i-1], dp[i][j-1])

    # Return the maximum energy
    return max(dp[n][i] for i in range(n+1))

def largest_prime_factor(n: int) -> int:
    if n < 2:
        raise ValueError("n must be greater than 1")
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return n // i
    return n

