def is_prime(num):
    if num <= 1:
        return False
    if num in [2, 3]:
        return True

    if num % 2 == 0 or num % 3 == 0:
        return False

    for i in range(5, int(num ** 0.5) + 1, 6):
        if num % i == 0 or num % (i + 2) == 0:
            return False

    return True

def catalan_number(n: int) -> int:

    if n < 0:
        raise ValueError("n must be non-negative")

    if n == 0:
        return 1

    count = 0
    for i in range(n):
        count += catalan_number(i) * catalan_number(n-i-1)

    return count

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14

    moves = 0
    for i in range(n - 1):
        moves += (2 ** i) * (2 * i + 1)
    return moves + 2 ** n - 1

def total_smoked_cigarettes(n, k):
    total = n
    while n >= k:
        total += n // k
        n = n // k
    return total
